fn toggle_case(s: Vec<char>) -> Vec<char> {
    s.into_iter()
        .map(|c| {
            let code = c as u8;
            if (b'a'..=b'z').contains(&code) {
                // Lowercase to uppercase: subtract 32
                (code - 32) as char
            } else if (b'A'..=b'Z').contains(&code) {
                // Uppercase to lowercase: add 32
                (code + 32) as char
            } else {
                // Non-alphabetic: unchanged
                c
            }
        })
        .collect()
}